"""Embeds Inter as a C byte array for the text engine.

    python gpu/extern/gen_font_header.py Inter-VariableFont_opsz,wght.ttf

(the variable font from https://rsms.me/inter, as Blender ships it)

writes gpu/extern/font_inter.h (g_font_inter_variable). With FreeType, BUI
draws its weights 400 and 700 at the text's optical size, like Blender's BLF.
Inter: SIL Open Font License 1.1, see gpu/extern/Inter-LICENSE.txt.
"""

import sys
from pathlib import Path

OUT = Path(__file__).resolve().parent / "font_inter.h"


def main() -> None:
    data = Path(sys.argv[1]).read_bytes()
    rows = [",".join(str(b) for b in data[i : i + 40]) for i in range(0, len(data), 40)]
    OUT.write_text(
        "/* Generated by gpu/extern/gen_font_header.py. Do not edit.\n"
        " * Inter (variable: opsz 14-32, wght 100-900), Copyright 2020 The Inter Project Authors,\n"
        " * SIL Open Font License 1.1 (gpu/extern/Inter-LICENSE.txt). Blender's UI font. */\n\n"
        f"static const unsigned char g_font_inter_variable[{len(data)}] = {{\n"
        + ",\n".join(rows)
        + "};\n",
        encoding="utf-8",
        newline="\n",
    )
    print(f"wrote {OUT} ({len(data)} bytes)")


if __name__ == "__main__":
    main()
